import glob, os, shutil, subprocess, json, sys

def fail(msg):
    print(json.dumps({"results": [], "harness_error": msg}))
    sys.exit(0)

root = os.environ.get("DOTNET_ROOT") or "/usr/local/share/dotnet"
cwd = os.getcwd()
csc_hits = sorted(glob.glob(os.path.join(root, "sdk", "*", "Roslyn", "bincore", "csc.dll")))
if not csc_hits:
    fail("csc.dll not found under DOTNET_ROOT")
csc = csc_hits[-1]

def pack(name):
    return sorted(glob.glob(os.path.join(root, "packs", name, "*", "ref", "net8.0", "*.dll")))

core = pack("Microsoft.NETCore.App.Ref")
web = pack("Microsoft.AspNetCore.App.Ref")
if not core or not web:
    fail("reference assemblies not found")

seen = {}
for p in core + web:
    seen.setdefault(os.path.basename(p), p)
with open("refs.rsp", "w") as f:
    for p in seen.values():
        f.write('-r:"' + p + '"\n')

shutil.copyfile("block-0.txt", "candidate.cs")

try:
    c = subprocess.run(["dotnet", csc, "-nologo", "-target:exe", "-out:Candidate.dll", "@refs.rsp", "candidate.cs", "Harness.cs"], cwd=cwd, capture_output=True, text=True, timeout=5)
except subprocess.TimeoutExpired:
    fail("compile timeout")
if c.returncode != 0:
    fail("compile failed: " + (c.stdout + c.stderr)[-1500:])

with open("Candidate.runtimeconfig.json", "w") as f:
    json.dump({"runtimeOptions": {"tfm": "net8.0", "framework": {"name": "Microsoft.AspNetCore.App", "version": "8.0.0"}}}, f)

try:
    r = subprocess.run(["dotnet", "Candidate.dll"], cwd=cwd, capture_output=True, text=True, timeout=5)
except subprocess.TimeoutExpired:
    fail("run timeout")

lines = [l for l in r.stdout.splitlines() if l.strip().startswith("{")]
if not lines:
    fail("no output: " + r.stderr[-1000:])
print(lines[-1])

