using System;
using System.Collections.Generic;
using System.ComponentModel.DataAnnotations;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text.Json;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Abstractions;
using Microsoft.AspNetCore.Mvc.ModelBinding;
using Microsoft.AspNetCore.Routing;

public static class Harness
{
    public static int Main()
    {
        TextWriter realOut = Console.Out;
        var results = new List<object>();
        try
        {
            using var doc = JsonDocument.Parse(File.ReadAllText("inputs.json"));
            Type ctrlType = null;
            foreach (var t in typeof(Harness).Assembly.GetTypes())
            {
                if (!t.IsAbstract && typeof(ControllerBase).IsAssignableFrom(t)) { ctrlType = t; break; }
            }
            if (ctrlType == null) throw new InvalidOperationException("no ControllerBase subclass in candidate");

            MethodInfo action = null;
            foreach (var m in ctrlType.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly))
            {
                if (typeof(IActionResult).IsAssignableFrom(m.ReturnType)) { action = m; break; }
            }
            if (action == null) throw new InvalidOperationException("no action method found");

            ParameterInfo p = action.GetParameters().FirstOrDefault();
            if (p == null) throw new InvalidOperationException("action has no parameter");

            foreach (var item in doc.RootElement.EnumerateArray())
            {
                string id = item.GetProperty("id").GetString();
                var buf = new StringWriter();
                Console.SetOut(buf);
                try
                {
                    object value = ReadValue(item, p.Name);
                    int status = RunAction(ctrlType, action, p, value);
                    Console.SetOut(realOut);
                    results.Add(new { id, actual = new { status } });
                }
                catch (Exception ex)
                {
                    Console.SetOut(realOut);
                    results.Add(new { id, error = ex.GetType().FullName + ": " + ex.Message });
                }
            }
        }
        catch (Exception ex)
        {
            Console.SetOut(realOut);
            Console.WriteLine(JsonSerializer.Serialize(new { results, harness_error = ex.ToString() }));
            return 0;
        }
        Console.SetOut(realOut);
        Console.WriteLine(JsonSerializer.Serialize(new { results }));
        return 0;
    }

    static object ReadValue(JsonElement item, string name)
    {
        JsonElement inp;
        if (!item.TryGetProperty("input", out inp) || inp.ValueKind != JsonValueKind.Object) return null;
        JsonElement v;
        if (!inp.TryGetProperty(name, out v) || v.ValueKind == JsonValueKind.Null) return null;
        if (v.ValueKind != JsonValueKind.String) throw new InvalidOperationException("non-string input for " + name);
        return v.GetString();
    }

    static int RunAction(Type ctrlType, MethodInfo action, ParameterInfo p, object value)
    {
        var ms = new ModelStateDictionary();
        var vctx = new ValidationContext(new object()) { MemberName = p.Name, DisplayName = p.Name };
        foreach (ValidationAttribute attr in p.GetCustomAttributes(typeof(ValidationAttribute), false))
        {
            ValidationResult r = attr.GetValidationResult(value, vctx);
            if (r != null) ms.AddModelError(p.Name, r.ErrorMessage ?? "invalid");
        }

        var ctrl = (ControllerBase)Activator.CreateInstance(ctrlType);
        ctrl.ControllerContext = new ControllerContext(
            new ActionContext(new DefaultHttpContext(), new RouteData(), new ActionDescriptor(), ms));

        object res;
        try
        {
            res = action.Invoke(ctrl, new object[] { value });
        }
        catch (TargetInvocationException tie)
        {
            throw tie.InnerException ?? tie;
        }

        if (res == null) throw new InvalidOperationException("action returned null");
        PropertyInfo scp = res.GetType().GetProperty("StatusCode");
        if (scp != null)
        {
            object sc = scp.GetValue(res);
            if (sc is int code) return code;
        }
        throw new InvalidOperationException("action result has no status code");
    }
}

using System;
using System.Collections.Generic;
using System.ComponentModel.DataAnnotations;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text.Json;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;

public static class HarnessMain
{
    public static int Main(string[] args)
    {
        TextWriter realOut = Console.Out;
        var results = new List<Dictionary<string, object>>();
        string harnessError = null;
        try
        {
            string text = File.ReadAllText(Path.Combine(Directory.GetCurrentDirectory(), "inputs.json"));
            using JsonDocument doc = JsonDocument.Parse(text);
            Type controllerType = Assembly.GetExecutingAssembly().GetTypes()
                .FirstOrDefault(t => !t.IsAbstract && typeof(ControllerBase).IsAssignableFrom(t));
            if (controllerType == null) throw new InvalidOperationException("no controller type found in candidate");
            MethodInfo action = controllerType
                .GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly)
                .FirstOrDefault(m => typeof(IActionResult).IsAssignableFrom(m.ReturnType) && m.GetParameters().Length == 1);
            if (action == null) throw new InvalidOperationException("no single-parameter action found");
            ParameterInfo param = action.GetParameters()[0];

            foreach (JsonElement c in doc.RootElement.EnumerateArray())
            {
                var entry = new Dictionary<string, object>();
                entry["id"] = c.GetProperty("id").ToString();
                try
                {
                    object value = ReadValue(c, param.Name);
                    entry["actual"] = RunCase(controllerType, action, param, value);
                }
                catch (Exception ex)
                {
                    Exception root = ex is TargetInvocationException tie && tie.InnerException != null ? tie.InnerException : ex;
                    entry["error"] = root.GetType().Name + ": " + root.Message;
                }
                results.Add(entry);
            }
        }
        catch (Exception ex)
        {
            harnessError = ex.GetType().Name + ": " + ex.Message;
        }

        var final = new Dictionary<string, object> { ["results"] = results };
        if (harnessError != null) final["harness_error"] = harnessError;
        realOut.WriteLine(JsonSerializer.Serialize(final));
        return 0;
    }

    static object ReadValue(JsonElement c, string name)
    {
        if (!c.TryGetProperty("input", out JsonElement input) || input.ValueKind != JsonValueKind.Object) return null;
        if (!input.TryGetProperty(name, out JsonElement v)) return null;
        if (v.ValueKind == JsonValueKind.Null) return null;
        if (v.ValueKind == JsonValueKind.String) return v.GetString();
        return v.GetRawText();
    }

    static Dictionary<string, object> RunCase(Type controllerType, MethodInfo action, ParameterInfo param, object value)
    {
        var controller = (ControllerBase)Activator.CreateInstance(controllerType);
        controller.ControllerContext = new ControllerContext { HttpContext = new DefaultHttpContext() };
        foreach (ValidationAttribute attr in param.GetCustomAttributes(typeof(ValidationAttribute), true))
        {
            var vc = new ValidationContext(new object()) { MemberName = param.Name };
            ValidationResult r = attr.GetValidationResult(value, vc);
            if (r != ValidationResult.Success)
                controller.ModelState.AddModelError(param.Name, r.ErrorMessage ?? "invalid");
        }

        TextWriter saved = Console.Out;
        Console.SetOut(new StringWriter());
        object res;
        try
        {
            res = action.Invoke(controller, new object[] { value });
        }
        finally
        {
            Console.SetOut(saved);
        }

        if (res != null)
        {
            PropertyInfo sp = res.GetType().GetProperty("StatusCode");
            if (sp != null && sp.GetValue(res) is int code)
                return new Dictionary<string, object> { ["status"] = code };
        }
        throw new InvalidOperationException("action result has no status code");
    }
}
